/**
 * Pull the Airtable-bound fields out of one quotation tab.
 *
 * Kristine's mapping is written in cell addresses (B35, B36, B38, E119). We honor those
 * as the expected positions, but we *find* each value by its label in column A instead of
 * reading the address blind. The quotation template gets rows inserted into it — the
 * `QU # (DATE)` tab and the `MAIN` tab in the same workbook already disagree by four rows
 * on where the totals block starts. A blind read of E119 would silently pick up whatever
 * moved into that cell; a label read either finds `RND PACKAGE COST` or reports that it
 * could not.
 *
 * Every anchor still carries its expected row. When the two disagree we take the label and
 * raise a drift warning, so the sheet drifting is visible rather than silent.
 */

/**
 * Exact `Service` choices from the Projects table. Several carry a trailing space that is
 * part of the stored value — 'Recording ' is not 'Recording'. Airtable rejects a write that
 * does not match a choice character for character, so these are copied verbatim.
 * Refresh with: node scripts/refresh-choices.js
 */
const SERVICE_CHOICES = [
  'AV Integration',
  'Video',
  'Other',
  'Recording ',
  'Mixing ',
  'Editing ',
  'Lobby Events / Rental',
  'Sound Design',
  'Sonic Branding ',
  'In-Studio Listening / Preview Session ',
  'Music Composition',
  'Studio Rental',
  'BUYOUT',
  'Video post-production',
  'Directing ',
];

const DEFAULTS = {
  serviceChoices: SERVICE_CHOICES,
  // Applied only when creating a record, never on update. A record with no Status is
  // invisible in the tracker's grouped views, and the sheet has no Status column to read.
  statusOnCreate: 'Awaiting Quote Approval',
  // 'product'         -> Project Title = PRODUCT, as specified.
  // 'company-product' -> 'HARAYA DEL ROSARIO - AUDIOBOOK PRODUCTION', matching how the
  //                      existing 18 records are titled (client first). Opt in.
  projectTitleMode: 'product',
};

const ANCHORS = {
  company: { label: 'AGENCY/COMPANY', valueCol: 1, expectedRow: 35 },
  contact: { label: 'PRODUCER/MAIN CONTACT', valueCol: 1, expectedRow: 36 },
  product: { label: 'PRODUCT', valueCol: 1, expectedRow: 37 },
  services: { label: 'PROJECT DETAILS', valueCol: 1, expectedRow: 38 },
  // Rows below confirmed against the live sheet on 2026-09-20, by reading what the Sheets
  // API actually returned. Note these are one lower than the handoff's cell references:
  // the spec's E119 is the TOTAL row, not RND PACKAGE COST. See README, 'Approved cost'.
  rndPackageCost: { label: 'RND PACKAGE COST', valueCol: 4, expectedRow: 120 },
  total: { label: 'TOTAL', valueCol: 4, expectedRow: 119 },
  totalNet: { label: 'TOTAL NET', valueCol: 4, expectedRow: 116 },
};

const text = (v) => String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim();

/** Uppercase, collapse whitespace, drop a trailing colon. For comparing labels only. */
const label = (v) => text(v).replace(/[:：]+$/, '').trim().toUpperCase();

const at = (grid, row, col) => text(grid[row] && grid[row][col]);

/** A1-style address for a zero-indexed row/col, so warnings name a cell a human can open. */
function address(row, col) {
  let n = col + 1;
  let name = '';
  while (n > 0) {
    const rem = (n - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    n = Math.floor((n - 1) / 26);
  }
  return `${name}${row + 1}`;
}

/**
 * Locate a label in column A. Exact match after normalizing, which is what keeps
 * 'TOTAL' from matching 'TOTAL NET', 'TOTAL HOURS:' or ' ACTUALS TOTAL'.
 * Column A only — the MAIN tab carries a second quotation block in columns K-S with its
 * own 'TOTAL' and 'QU CODE:' rows, and that block is not part of this mapping.
 */
function findLabelRow(grid, wanted) {
  const want = label(wanted);
  for (let r = 0; r < grid.length; r++) {
    if (label(grid[r] && grid[r][0]) === want) return r;
  }
  return -1;
}

/** '48,782.22' -> 48782.22 | ' - ' -> null | '' -> null | '(1,200)' -> -1200 */
function parseMoney(raw) {
  const s = text(raw);
  if (!s) return null;
  if (/^[-–—\s]*$/.test(s)) return null;
  const negative = /^\(.*\)$/.test(s);
  const digits = s.replace(/[()]/g, '').replace(/[^0-9.-]/g, '');
  if (!digits || !/[0-9]/.test(digits)) return null;
  const n = Number(digits);
  if (!Number.isFinite(n)) return null;
  return negative ? -Math.abs(n) : n;
}

/**
 * 'RECORDING, DIRECTING' -> ['Recording ', 'Directing ']
 *
 * Whole string first: three of the real choices contain a slash or hyphen
 * ('Lobby Events / Rental', 'Video post-production'), so splitting eagerly would shred
 * them. Only commas and semicolons split. Anything that does not match a choice exactly
 * is reported rather than guessed at — a wrong multi-select is harder to notice than a
 * missing one.
 */
function mapServices(raw, choices) {
  const source = text(raw);
  const matched = [];
  const unmatched = [];
  if (!source) return { services: matched, unmatched };

  const lookup = new Map(choices.map((c) => [label(c), c]));

  const whole = lookup.get(label(source));
  if (whole) return { services: [whole], unmatched };

  for (const token of source.split(/[,;]+/)) {
    const t = text(token);
    if (!t) continue;
    const hit = lookup.get(label(t));
    if (hit) {
      if (!matched.includes(hit)) matched.push(hit);
    } else if (!unmatched.includes(t)) {
      unmatched.push(t);
    }
  }
  return { services: matched, unmatched };
}

/**
 * The QU code lives in a merged cell written as free text — 'QU CODE: QU-18135' — not as
 * a label/value pair like the rows above it. It may also be blank, because the number only
 * exists after the quote has been through Xero.
 */
function extractQuNumber(grid) {
  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c <= 1; c++) {
      const cell = at(grid, r, c);
      const m = /^QU\s*CODE\s*[:：]?\s*(.*)$/i.exec(cell);
      if (!m) continue;
      const inline = text(m[1]);
      const value = inline || at(grid, r, c + 1);
      if (value) return { quNumber: value, row: r, col: c };
    }
  }
  return { quNumber: null, row: -1, col: -1 };
}

/**
 * Reduce a QU cell to comparable digits. The tracker holds 'QU-17902', 'QU- 18006',
 * 'QU-' and 'QU- 17969, 17972, 17973' — string equality is not a usable key across those.
 * Used only for the fallback match; the record id written back to the sheet is the real key.
 */
function normalizeQu(raw) {
  const nums = text(raw).match(/\d{3,}/g);
  return nums ? nums.join(',') : null;
}

/**
 * @param {Array<Array<string>>} grid  Row-major values of one quotation tab, A1 at [0][0].
 * @param {object} [options]
 * @returns {{fields: object, meta: object, warnings: string[]}}
 */
function extractQuotation(grid, options) {
  const config = Object.assign({}, DEFAULTS, options || {});
  const warnings = [];
  const found = {};

  for (const [key, anchor] of Object.entries(ANCHORS)) {
    const row = findLabelRow(grid, anchor.label);
    if (row === -1) {
      found[key] = { row: -1, value: '' };
      continue;
    }
    if (row !== anchor.expectedRow - 1) {
      warnings.push(
        `Template drift: '${anchor.label}' expected on row ${anchor.expectedRow}, found on ` +
          `row ${row + 1}. Read ${address(row, anchor.valueCol)} instead of ` +
          `${address(anchor.expectedRow - 1, anchor.valueCol)}.`
      );
    }
    found[key] = { row, value: at(grid, row, anchor.valueCol) };
  }

  for (const key of ['company', 'contact', 'product', 'services']) {
    if (found[key].row === -1) {
      warnings.push(`Missing label '${ANCHORS[key].label}' in column A — nothing to read for ${key}.`);
    }
  }

  const company = found.company.value;
  const contact = found.contact.value;
  const product = found.product.value;

  // House format, matching all 18 existing records: 'Steve Huang / LAKIWIN'.
  const contactCompany = [contact, company].filter(Boolean).join(' / ');
  if (!contact || !company) {
    warnings.push(
      `CONTACT Name / COMPANY built from a partial pair (contact='${contact}', company='${company}').`
    );
  }

  const { services, unmatched } = mapServices(found.services.value, config.serviceChoices);
  if (unmatched.length) {
    warnings.push(
      `PROJECT DETAILS has no matching Service choice for: ${unmatched
        .map((u) => `'${u}'`)
        .join(', ')}. Left off the record — add the choice in Airtable or fix the sheet.`
    );
  }

  // Approved cost: the rounded package figure is what the client signs off on. Fall back to
  // TOTAL when it has not been filled in, so the record is never silently zero.
  const rnd = parseMoney(found.rndPackageCost.value);
  const total = parseMoney(found.total.value);
  let approvedCost = rnd;
  let approvedCostSource = 'RND PACKAGE COST';
  if (approvedCost === null) {
    approvedCost = total;
    approvedCostSource = 'TOTAL (fallback)';
    warnings.push(
      `RND PACKAGE COST (${address(found.rndPackageCost.row, ANCHORS.rndPackageCost.valueCol)}) ` +
        `is empty — used TOTAL instead` + (total === null ? ', which is also empty.' : ` (${total}).`)
    );
  }
  if (approvedCost === null) {
    approvedCostSource = 'none';
    warnings.push('No approved cost found — Approved Cost (Local) will be left empty.');
  }

  const qu = extractQuNumber(grid);

  const projectTitle =
    config.projectTitleMode === 'company-product'
      ? [company, product].filter(Boolean).join(' - ')
      : product;

  const fields = {};
  if (projectTitle) fields['Project Title'] = projectTitle;
  if (contactCompany) fields['CONTACT Name / COMPANY'] = contactCompany;
  if (services.length) fields['Service'] = services;
  if (approvedCost !== null) fields['Approved Cost (Local)'] = approvedCost;
  if (qu.quNumber) fields['QU Number'] = qu.quNumber;

  return {
    fields,
    meta: {
      quNumber: qu.quNumber,
      quNumberNormalized: normalizeQu(qu.quNumber),
      quCell: qu.row === -1 ? null : address(qu.row, qu.col),
      approvedCostSource,
      rndPackageCost: rnd,
      total,
      totalNet: parseMoney(found.totalNet.value),
      unmatchedServices: unmatched,
      statusOnCreate: config.statusOnCreate,
      readFrom: Object.fromEntries(
        Object.entries(found).map(([k, v]) => [
          k,
          v.row === -1 ? null : address(v.row, ANCHORS[k].valueCol),
        ])
      ),
    },
    warnings,
  };
}

/**
 * Decide what a quotation should do to the tracker: create, update, or nothing.
 *
 * Pure. No network. The n8n workflow reads the sheet and the table, hands both to
 * decideAction, and performs whatever comes back. Keeping the decision separate from the
 * I/O is what makes it testable, and this is the part worth testing — a sync that creates
 * a second record every run is worse than no sync at all.
 *
 * Three rules hold the whole thing up:
 *
 *  1. The record id written back into the sheet is the key. Not the QU number. The tracker
 *     holds 'QU-', 'QU- 18006' and 'QU- 17969, 17972, 17973'; the QU also does not exist
 *     until the quote has been through Xero, which is after the first sync. It is a
 *     fallback, never the primary.
 *  2. Never write an empty value over a populated one. The sheet is one view of a project;
 *     people also type directly into Airtable. A blank cell means 'the sheet does not know',
 *     not 'set this to blank'.
 *  3. If nothing changed, write nothing. Keeps revision history readable and keeps the
 *     run cheap.
 */


/** Fields the sync owns. Anything else on the record is somebody else's and is left alone. */
const SYNCED_FIELDS = [
  'Project Title',
  'CONTACT Name / COMPANY',
  'Service',
  'Approved Cost (Local)',
  'QU Number',
];

/**
 * Written when the record is created, then never touched again.
 *
 * `Project Title` is not in Kristine's mapping — it is here so a new record is not
 * nameless in the tracker's primary column. But the sheet's PRODUCT cell is a rate
 * description, and people write something better by hand: the live tracker had
 * 'Haraya Del Rosario - The 90-Day Leadership Field Manual' where the sheet says
 * 'AUDIOBOOK PRODUCTION - PER DAY RATE'. Syncing that field on update would replace a
 * human's title with a worse one on every run, so it seeds and then stays out of the way.
 */
const CREATE_ONLY_FIELDS = ['Project Title'];

const sameValue = (a, b) => {
  if (Array.isArray(a) || Array.isArray(b)) {
    const x = Array.isArray(a) ? a.slice().sort() : [];
    const y = Array.isArray(b) ? b.slice().sort() : [];
    return x.length === y.length && x.every((v, i) => v === y[i]);
  }
  if (typeof a === 'number' || typeof b === 'number') {
    const x = Number(a);
    const y = Number(b);
    if (Number.isFinite(x) && Number.isFinite(y)) return Math.abs(x - y) < 0.005;
  }
  return String(a === undefined || a === null ? '' : a) === String(b === undefined || b === null ? '' : b);
};

const isEmpty = (v) =>
  v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);

/**
 * @param {object} extracted        extractQuotation() output
 * @param {object} [options]
 * @param {string|null} [options.storedRecordId]  record id read back from the sheet
 * @param {Array}  [options.existingRecords]      [{ id, fields }] from the Projects table
 * @param {string|null} [options.sourceFileId]    Drive file id, for the audit column
 * @param {string} [options.statusOnCreate]
 */
function decideAction(extracted, options) {
  const opts = options || {};
  const existing = opts.existingRecords || [];
  const notes = [];
  const incoming = extracted.fields || {};

  let target = null;
  let matchedBy = null;

  if (opts.storedRecordId) {
    target = existing.find((r) => r.id === opts.storedRecordId) || null;
    if (target) {
      matchedBy = 'record id from sheet';
    } else {
      notes.push(
        `The sheet points at record ${opts.storedRecordId}, which is not in the table ` +
          `(deleted, or the sheet was copied from another project). Falling back to the QU number.`
      );
    }
  }

  if (!target) {
    const wantedQu = extracted.meta && extracted.meta.quNumberNormalized;
    if (wantedQu) {
      const hits = existing.filter((r) => normalizeQu(r.fields && r.fields['QU Number']) === wantedQu);
      if (hits.length === 1) {
        target = hits[0];
        matchedBy = 'QU number';
      } else if (hits.length > 1) {
        // Two records carrying the same QU is a data problem in the tracker. Picking one
        // at random would quietly corrupt whichever we lost.
        return {
          action: 'skip',
          recordId: null,
          fields: {},
          matchedBy: null,
          reason:
            `QU ${extracted.meta.quNumber} matches ${hits.length} records ` +
            `(${hits.map((h) => h.id).join(', ')}). Refusing to guess which one to update.`,
          notes,
          warnings: extracted.warnings || [],
        };
      }
    }
  }

  if (!target) {
    const fields = {};
    for (const key of SYNCED_FIELDS) {
      if (!isEmpty(incoming[key])) fields[key] = incoming[key];
    }
    if (opts.statusOnCreate) fields['Status'] = opts.statusOnCreate;
    if (opts.sourceFileId && opts.includeSourceFileField) {
      fields['_sync_source_file'] = opts.sourceFileId;
    }
    return {
      action: 'create',
      recordId: null,
      fields,
      matchedBy: null,
      reason: 'No record id in the sheet and no QU match — this quotation is new to the tracker.',
      notes,
      warnings: extracted.warnings || [],
    };
  }

  const current = target.fields || {};
  const fields = {};
  const changes = [];
  const held = [];

  for (const key of SYNCED_FIELDS) {
    const next = incoming[key];

    if (CREATE_ONLY_FIELDS.includes(key)) {
      // Surfaced rather than silent: someone comparing the sheet to the tracker should be
      // able to see that the two disagree and that the sync chose not to intervene.
      if (!isEmpty(next) && !isEmpty(current[key]) && !sameValue(next, current[key])) {
        notes.push(
          `${key} differs — sheet says ${JSON.stringify(next)}, tracker says ` +
            `${JSON.stringify(current[key])}. Left as it is; ${key} is only written when a ` +
            `record is first created.`
        );
      }
      continue;
    }

    if (isEmpty(next)) {
      // Rule 2. Only worth mentioning when there is something there to protect.
      if (!isEmpty(current[key])) held.push(key);
      continue;
    }
    if (!sameValue(next, current[key])) {
      fields[key] = next;
      changes.push(
        `${key}: ${JSON.stringify(current[key] === undefined ? null : current[key])} -> ${JSON.stringify(next)}`
      );
    }
  }

  if (held.length) {
    notes.push(`Sheet had nothing for ${held.join(', ')} — left the tracker's values alone.`);
  }

  if (!changes.length) {
    return {
      action: 'skip',
      recordId: target.id,
      fields: {},
      matchedBy,
      reason: `Matched ${target.id} by ${matchedBy}; every synced field already agrees.`,
      notes,
      warnings: extracted.warnings || [],
    };
  }

  return {
    action: 'update',
    recordId: target.id,
    fields,
    matchedBy,
    reason: `Matched ${target.id} by ${matchedBy}. Changing: ${changes.join('; ')}.`,
    notes,
    warnings: extracted.warnings || [],
  };
}

/**
 * The glue between n8n's HTTP nodes and the two pure modules.
 *
 * Everything here is still pure — it takes the raw shapes the Google Sheets and Airtable
 * APIs return and produces a decision plus a human-readable summary. The Code node in the
 * workflow is this file, extract.js and sync.js concatenated by scripts/build-workflow.js,
 * with a four-line n8n adapter on the end. Same reason Posty does it: the code that is
 * tested is the code that ships.
 */



// --- link parsing (sliced out verbatim into the Parse Request node) ---------

/**
 * Google URLs all carry a `/d/<id>` segment, so matching that alone accepts a Doc, a
 * deck or an uploaded file just as happily as a spreadsheet. It then fails much later,
 * at the Sheets API, as "Requested entity was not found" — which tells the person who
 * pasted it nothing at all. Someone pasted a Google Doc link on 22 Sept and got exactly
 * that. These are matched first so the complaint can name what they actually pasted.
 */
const WRONG_LINK_KINDS = [
  [/\/document\/d\//, 'a Google Doc'],
  [/\/presentation\/d\//, 'a Google Slides deck'],
  [/\/forms\/d\//, 'a Google Form'],
  [/\/file\/d\//, 'a file stored in Drive (an upload, not a Google Sheet)'],
];

/**
 * Accepts what a person will actually paste: a full edit URL, a sharing URL, or the bare
 * id. Only `/spreadsheets/d/` counts as a link — anything else is rejected here rather
 * than turned into a request that cannot work.
 */
function parseFileId(raw) {
  const s = String(raw === null || raw === undefined ? '' : raw).trim();
  if (!s) return null;
  for (const pair of WRONG_LINK_KINDS) if (pair[0].test(s)) return null;
  const fromUrl = /\/spreadsheets\/d\/([a-zA-Z0-9_-]{20,})/.exec(s);
  if (fromUrl) return fromUrl[1];
  if (/^[a-zA-Z0-9_-]{20,}$/.test(s)) return s;
  return null;
}

/** null when the link is usable, otherwise the sentence to show the person. */
function describeLinkProblem(raw) {
  const s = String(raw === null || raw === undefined ? '' : raw).trim();
  if (!s) return 'No link was given. Paste the link to the quotation Google Sheet.';
  for (const pair of WRONG_LINK_KINDS) {
    if (pair[0].test(s)) {
      return (
        `That link points at ${pair[1]}, not a Google Sheet. Open the quotation ` +
        `spreadsheet and copy the link from the address bar — a Sheet's link contains ` +
        `/spreadsheets/d/.`
      );
    }
  }
  if (!parseFileId(s)) {
    return (
      `That does not look like a Google Sheet link or id: ${JSON.stringify(s)}. ` +
      `Paste the full link from the address bar.`
    );
  }
  return null;
}

// --- end link parsing -------------------------------------------------------

/**
 * The `_hitsync` tab holds the Airtable record id in A2. The tab may not exist yet — for
 * every quotation file made before this sync did — in which case the read node fails soft
 * and we get nothing. That is a normal first run, not an error.
 */
function readStoredRecordId(values) {
  const cell = values && values[0] && values[0][0];
  const s = String(cell === null || cell === undefined ? '' : cell).trim();
  return /^rec[A-Za-z0-9]{14}$/.test(s) ? s : null;
}

/** Airtable REST hands back { records: [{ id, fields }] }, possibly across pages. */
function collectAirtableRecords(pages) {
  const out = [];
  for (const page of [].concat(pages || [])) {
    const records = (page && page.records) || [];
    for (const r of records) out.push({ id: r.id, fields: r.fields || {} });
  }
  return out;
}

/** One readable block for the form's result screen. Kristine reads this, not the JSON. */
function summarize(state) {
  const { decision, extracted, preview } = state;
  const lines = [];
  const verb = { create: 'Created', update: 'Updated', skip: 'No change' }[decision.action];

  lines.push(preview ? `PREVIEW — nothing was written.` : `${verb}.`);
  lines.push('');
  lines.push(decision.reason);

  if (decision.action !== 'skip') {
    lines.push('');
    lines.push(decision.action === 'create' ? 'Fields written:' : 'Fields changed:');
    for (const [k, v] of Object.entries(decision.fields)) {
      lines.push(`  ${k}: ${Array.isArray(v) ? v.join(', ') : v}`);
    }
  }

  const notes = [].concat(decision.notes || [], decision.warnings || []);
  if (notes.length) {
    lines.push('');
    lines.push('Worth checking:');
    for (const n of notes) lines.push(`  - ${n}`);
  }

  lines.push('');
  lines.push(`Approved cost taken from: ${extracted.meta.approvedCostSource}`);

  return lines.join('\n');
}

/**
 * @param {object} ctx
 * @param {Array<Array<string>>} ctx.sheetValues     values from <tab>!A1:T200
 * @param {Array<Array<string>>} [ctx.syncTabValues] values from _hitsync!A2, if the tab exists
 * @param {Array|object} [ctx.airtablePages]         one or more Airtable list responses
 * @param {string} ctx.fileId
 * @param {boolean} [ctx.preview]
 * @param {object} [ctx.options]
 */
function runDecision(ctx) {
  const extracted = extractQuotation(ctx.sheetValues || [], ctx.options);
  const storedRecordId = readStoredRecordId(ctx.syncTabValues);
  const existingRecords = collectAirtableRecords(ctx.airtablePages);

  const decision = decideAction(extracted, {
    storedRecordId,
    existingRecords,
    sourceFileId: ctx.fileId,
    statusOnCreate: (ctx.options && ctx.options.statusOnCreate) || DEFAULTS.statusOnCreate,
    includeSourceFileField: Boolean(ctx.options && ctx.options.includeSourceFileField),
  });

  const preview = Boolean(ctx.preview);
  const state = { extracted, decision, storedRecordId, preview, fileId: ctx.fileId };

  return {
    action: preview ? 'preview' : decision.action,
    plannedAction: decision.action,
    recordId: decision.recordId,
    fields: decision.fields,
    // The write-back only needs to happen when a record is created and the sheet does not
    // already point at one. An update already knows which record it is talking to.
    needsRecordIdWriteback: !preview && decision.action === 'create',
    storedRecordId,
    matchedBy: decision.matchedBy,
    reason: decision.reason,
    notes: decision.notes,
    warnings: decision.warnings,
    meta: extracted.meta,
    summary: summarize(state),
  };
}

/**
 * The Airtable call this run needs, or null when there is nothing to write.
 *
 * Built here rather than in the workflow so that the create/update choice is covered by
 * tests instead of by an IF node nobody can unit-test. The HTTP node just executes
 * whatever method, url and body it is handed.
 */
function buildWriteRequest(result, cfg) {
  if (!result || result.action === 'preview' || result.plannedAction === 'skip') return null;
  const table = encodeURIComponent(cfg.table);
  const base = `https://api.airtable.com/v0/${cfg.baseId}/${table}`;

  if (result.plannedAction === 'create') {
    return { method: 'POST', url: base, body: { fields: result.fields, typecast: false } };
  }
  if (!result.recordId) return null;
  return {
    method: 'PATCH',
    url: `${base}/${result.recordId}`,
    body: { fields: result.fields, typecast: false },
  };
}

/**
 * Stamp the new record id into the quotation's `_hitsync` tab.
 *
 * Writes the header alongside the value so the tab explains itself to whoever opens it,
 * and so a file whose tab exists but is empty ends up correct either way. RAW, not
 * USER_ENTERED — a record id must never be interpreted by Sheets.
 */
function buildWritebackRequest(fileId, recordId, cfg) {
  if (!fileId || !recordId) return null;
  const range = encodeURIComponent(`${cfg.syncTab}!A1:A2`);
  return {
    method: 'PUT',
    url:
      `https://sheets.googleapis.com/v4/spreadsheets/${fileId}/values/${range}` +
      `?valueInputOption=RAW`,
    body: { values: [['airtable_record_id'], [recordId]] },
  };
}

// --- n8n adapter -----------------------------------------------------------
const input = $('Parse Request').first().json;
const decided = $('Decide').first().json;
const written = $('Write Tracker').first().json;

// On a create, Airtable's response carries the new record id. That id is the thing we
// stamp into the sheet, and it is what stops the next run creating a duplicate.
const recordId = (written && written.id) || decided.recordId || null;

const writeback = decided.needsRecordIdWriteback
  ? buildWritebackRequest(input.fileId, recordId, { syncTab: input.config.syncTab })
  : null;

return [{
  json: {
    recordId: recordId,
    needsWriteback: Boolean(writeback),
    writeback: writeback || {}
  }
}];

const decided = $('Decide').first().json;

let recordId = decided.recordId;
try {
  const prepared = $('Prepare Writeback').first().json;
  if (prepared && prepared.recordId) recordId = prepared.recordId;
} catch (e) {
  // Nothing was written this run — skip or preview. decided.recordId is already right.
}

return [{
  json: {
    result: decided.summary,
    action: decided.action,
    recordId: recordId,
    matchedBy: decided.matchedBy,
    warnings: decided.warnings
  }
}];
